package thaumcraft.verification;

import java.util.*;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import thaumcraft.registry.R5Content;
import thaumcraft.blocks.*;

@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ClientOuterFoundationVerification {
    private static boolean done;
    @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception {
        if(done||!"outer-foundation-client".equals(System.getProperty("thaumcraft.r3.phase")))return;var mc=net.minecraft.client.Minecraft.getInstance();if(!(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen)||mc.getOverlay()!=null)return;done=true;
        var result=new com.google.gson.JsonObject();var checks=new ArrayList<String>();
        try{
            var effects=net.neoforged.neoforge.client.DimensionSpecialEffectsManager.getForType(ResourceLocation.parse("thaumcraft:outer_lands"));if(!(effects instanceof thaumcraft.client.OuterDimensionEffects)||effects.skyType()!=net.minecraft.client.renderer.DimensionSpecialEffects.SkyType.NONE||effects.hasGround()||effects.getSunriseColor(.25f,0)!=null||!effects.isFoggyAt(-20,30))throw new AssertionError("Original dimension effects failed actual client registration");checks.add("Actual client registers original Outer Lands sky/cloud/fog effects");var fog=effects.getBrightnessDependentFogColor(net.minecraft.world.phys.Vec3.ZERO,1);if(Math.abs(fog.x-160/255.0*.15)>1e-9||Math.abs(fog.y-128/255.0*.15)>1e-9||Math.abs(fog.z-fog.x)>1e-9)throw new AssertionError("Original fog RGB differs");checks.add("Original fog RGB remains constant under daylight changes");
            var rendererField=net.minecraft.client.renderer.entity.EntityRenderDispatcher.class.getDeclaredField("renderers");rendererField.setAccessible(true);var renderer=((Map<?,?>)rendererField.get(mc.getEntityRenderDispatcher())).get(thaumcraft.entities.R5Entities.INHABITED_ZOMBIE.get());if(!(renderer instanceof net.minecraft.client.renderer.entity.ZombieRenderer host)||!host.getTextureLocation(null).toString().equals("thaumcraft:textures/models/czombie.png"))throw new AssertionError("Host renderer is not original czombie");checks.add("Actual entity renderer uses original inhabited zombie texture");
            for(String name:List.of("czombie","zombie_plate_armor","obelisk_side","obelisk_side_2","obelisk_cap","obelisk_cap_2")){var location=ResourceLocation.parse("thaumcraft:textures/models/"+name+".png");mc.getTextureManager().bindForSetup(location);if(mc.getTextureManager().getTexture(location).getId()<=0)throw new AssertionError("Texture not uploaded: "+name);checks.add("Original texture loads and uploads to GPU: "+name);}
            for(var block:List.of(R5Content.OBELISK.get(),R5Content.ELDRITCH_CAP.get())){var model=mc.getBlockRenderer().getBlockModel(block.defaultBlockState());if(!model.getParticleIcon().contents().name().toString().equals("thaumcraft:blocks/obsidiantile"))throw new AssertionError("Original obelisk particle sprite is missing or wrong");checks.add("Native baked obelisk/cap particle sprite resolves original obsidiantile");}
            var pos=net.minecraft.core.BlockPos.ZERO;var tile=new EldritchObeliskBlockEntity(pos,R5Content.OBELISK.get().defaultBlockState());var cap=new EldritchCapBlockEntity(pos,R5Content.ELDRITCH_CAP.get().defaultBlockState());var obelisk=mc.getBlockEntityRenderDispatcher().getRenderer(tile);var capRenderer=mc.getBlockEntityRenderDispatcher().getRenderer(cap);if(obelisk==null||capRenderer==null||obelisk.getRenderBoundingBox(tile).getYsize()!=5||obelisk.getViewDistance()!=96||capRenderer.getViewDistance()!=96)throw new AssertionError("Obelisk/cap native renderer, bounding box or draw distance missing");checks.add("Registered native obelisk and cap renderers use original bounding box and96block draw distance");
            var pose=new PoseStack();pose.translate(0,0,-500);var buffers=mc.renderBuffers().bufferSource();obelisk.render(tile,.5f,pose,buffers,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);capRenderer.render(cap,.5f,pose,buffers,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);buffers.endBatch();checks.add("Original cap OBJ and floating obelisk side panels submit and draw through actual GPU buffer");
            var method=Class.forName("thaumcraft.client.EldritchVoidRenderer").getDeclaredMethod("verticalCore",PoseStack.class,net.minecraft.client.renderer.MultiBufferSource.class,boolean.class,float.class);method.setAccessible(true);method.invoke(null,pose,buffers,true,3f);buffers.endBatch();checks.add("Near obelisk void planes draw through compiled native shader on actual GPU");
            if(org.lwjgl.opengl.GL11.glGetError()!=org.lwjgl.opengl.GL11.GL_NO_ERROR)throw new AssertionError("Native obelisk draw generated GL error");checks.add("Actual obelisk shader and side-panel GPU draws leave no OpenGL error");if(!(((Map<?,?>)rendererField.get(mc.getEntityRenderDispatcher())).get(thaumcraft.entities.R5Entities.PERMANENT_ITEM.get()) instanceof net.minecraft.client.renderer.entity.ItemEntityRenderer))throw new AssertionError("Permanent key renderer not registered");checks.add("Actual client registers native permanent Rune Key item renderer");
            for(int facing=0;facing<=6;facing++){var state=R5Content.ELDRITCH_LOCK.get().defaultBlockState().setValue(EldritchLockBlock.FACING,facing);var model=mc.getBlockRenderer().getBlockModel(state);for(var side:net.minecraft.core.Direction.values()){var quads=model.getQuads(state,side,net.minecraft.util.RandomSource.create(0));String expected="thaumcraft:blocks/deco_"+(side.ordinal()==facing?"2":"3");if(quads.size()!=1||!quads.getFirst().getSprite().contents().name().toString().equals(expected))throw new AssertionError("Lock baked face differs: "+facing+" "+side);}checks.add("Actual baked lock model retains original front/side textures, orientation"+facing);}
            result.addProperty("passed",true);result.addProperty("driver",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_RENDERER));
        }catch(Throwable error){result.addProperty("passed",false);result.addProperty("error",error.toString());}
        var payload=new com.google.gson.JsonObject();try(var artifact=new java.util.zip.ZipFile(java.nio.file.Path.of(System.getProperty("thaumcraft.r3.root"),"mod/build/libs/thaumcraft-1.21.1-0.2.0-r3-dev.jar").toFile())){var roots=List.of("thaumcraft/client/OuterDimensionEffects","thaumcraft/client/EldritchObeliskRenderer","thaumcraft/client/EldritchVoidRenderer","thaumcraft/client/OuterRoomRenderers","thaumcraft/client/LegacyParticles","thaumcraft/entities/InhabitedZombie","thaumcraft/entities/EldritchGuardian","thaumcraft/entities/R5Entities","thaumcraft/entities/BiomeSpawns","thaumcraft/blocks/EldritchObelisk","thaumcraft/blocks/EldritchCap","thaumcraft/registry/R5Content","thaumcraft/entities/PermanentItemEntity","thaumcraft/mixin/ItemAgeAccessor","thaumcraft/blocks/EldritchLock");for(var entry:Collections.list(artifact.entries())){String path=entry.getName();if(path.endsWith(".class")&&roots.stream().anyMatch(path::startsWith)){try(var stream=ClientOuterFoundationVerification.class.getClassLoader().getResourceAsStream(path)){if(stream==null)throw new AssertionError("Runtime class absent "+path);payload.addProperty(path,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(stream.readAllBytes())));}}}}
        result.add("payload_sha256",payload);result.add("checks",new com.google.gson.Gson().toJsonTree(checks));result.addProperty("count",checks.size());result.addProperty("time",java.time.Instant.now().toString());result.addProperty("manual_acceptance","pending");java.nio.file.Files.writeString(java.nio.file.Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/full_port/outer-foundation-client.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");mc.stop();
    }
    private ClientOuterFoundationVerification(){}
}
